#!/usr/bin/env python3
import sys
import argparse
import numpy as np
import h5py
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages

# Make diagnostic plots from the output of mergerTreeVariance.py: (1) the cumulative variance V(z) generated by splits occurring
# after redshift z, as a fraction of Var(N); (2) the contribution to Var(N) from splits binned in mass ratio x, separated into
# splits whose non-primary piece is below threshold (M'<m), near threshold ("terminal", m≤M'<4m) and well above it
# ("structural", M'≥4m); (3) the non-additivity ε = (Δ - count added by the split)/n₁ of structural splits as a function of
# x, compared with the heuristic for a power law n₁ ∝ M^(1+α): ε = (1-x)^(1+α)+x^(1+α)-1, or, for main-branch-only counts
# (statistic C), where only the primary carries the count forward, ε = (1-x)^(1+α)-1. α is not assumed: 1+α is the local
# slope d ln n₁/d ln M of the measured n₁ table at each split's parent, and the dashed line is the median heuristic over the
# same splits; (4) the measured σ_I² and ⟨ΣΔ²⟩-based estimate versus threshold mass.
# Andrew Benson (20-October-2026)

# Fixed categorical colors (assigned in order, by threshold index).
colors = ['#2a78d6','#eb6834','#1baf7a','#eda100','#e87ba4','#008300']

parser = argparse.ArgumentParser(prog='mergerTreeVariancePlot.py',description='Plot the split-by-split variance decomposition measured by mergerTreeVariance.py.')
parser.add_argument('fileName')
parser.add_argument('--outputFileName',action='store',default='mergerTreeVariance.pdf',help='the PDF file to which plots are written')
args = parser.parse_args()

def logarithmicSlope(table,logMass,omega,step=0.05):
    # The local slope d ln n₁/d ln M of an n₁ table (bilinear interpolation of ln n₁ between bin centers), by a backward
    # difference over 2×step in log₁₀ M (parents of the largest splits lie at the top edge of the table, where a forward point
    # would be clamped). Points where the table is empty or non-positive give NaN.
    logMassCenters = table['logMassCenters'][:]
    omegaCenters   = table['omegaCenters'  ][:]
    folds          = [table[name][:] for name in table.keys() if name.startswith('mean')]
    with np.errstate(invalid='ignore',divide='ignore'):
        logN1 = np.log(np.nanmean(np.array(folds),axis=0))
    def interpolate(x,y):
        i = np.clip((y-omegaCenters  [0])/(omegaCenters  [1]-omegaCenters  [0]),0.0,len(omegaCenters  )-1.000001)
        j = np.clip((x-logMassCenters[0])/(logMassCenters[1]-logMassCenters[0]),0.0,len(logMassCenters)-1.000001)
        i0, j0 = np.floor(i).astype(int), np.floor(j).astype(int)
        u , v  = i-i0, j-j0
        return (1.0-u)*(1.0-v)*logN1[i0,j0]+u*(1.0-v)*logN1[i0+1,j0]+(1.0-u)*v*logN1[i0,j0+1]+u*v*logN1[i0+1,j0+1]
    return (interpolate(logMass,omega)-interpolate(logMass-2.0*step,omega))/(2.0*step*np.log(10.0))

data = h5py.File(args.fileName,'r')
with PdfPages(args.outputFileName) as pdf:
    for statisticName in sorted(k for k in data.keys() if k.startswith('statistic')):
        statistic  = data[statisticName]
        thresholds = sorted(statistic.keys(),key=lambda k: statistic[k].attrs['massThreshold'])
        fig, axes  = plt.subplots(2,2,figsize=(11,8.5))
        fig.suptitle(statisticName+': '+statistic[thresholds[0]].attrs['description'],fontsize=11)
        massThreshold = []
        sigmaI2       = []
        sigmaI2Split  = []
        sigmaI2Error  = []
        for i, thresholdName in enumerate(thresholds):
            group      = statistic[thresholdName]
            color      = colors[i % len(colors)]
            m          = group.attrs['massThreshold']
            # Number of trees contributing per-split values (the analysis may write them for a subset of trees only).
            countTrees = group['splits'].attrs['treeCount'] if 'treeCount' in group['splits'].attrs else len(group['trees/count'])
            variance   = group.attrs['countVariance']
            mean       = group.attrs['countMean']
            delta      = group['splits/delta'        ][:]
            # The estimate of Δ² summed in the analysis (with the cross-product estimator this excludes the noise of the n₁
            # table, which squaring Δ would include). Older outputs lack it, so fall back to Δ².
            deltaSquared = group['splits/deltaSquared'][:] if 'deltaSquared' in group['splits'] else delta**2
            redshift   = group['splits/redshift'     ][:]
            massTotal  = group['splits/mass'         ][:]
            massSecond = group['splits/massSecondary'][:]
            n1Parent   = group['splits/n1Parent'     ][:]
            countAdded = group['splits/countAdded'   ][:]
            omegaSplit = group['splits/omega'        ][:]
            x          = massSecond/massTotal
            classes    = ((massSecond < m,':','M\'<m'),((massSecond >= m) & (massSecond < 4.0*m),'-','terminal'),(massSecond >= 4.0*m,'--','structural'))
            label      = r'$m=10^{{{:.2f}}}$'.format(np.log10(m))
            if variance <= 0.0:
                continue
            # Cumulative variance from splits at redshift < z.
            order = np.argsort(redshift)
            axes[0,0].plot(redshift[order],np.cumsum(deltaSquared[order])/countTrees/variance,color=color,lw=2,label=label)
            # Contribution to Var(N) in bins of x.
            bins = np.linspace(-4.0,np.log10(0.5),25)
            for select, style, name in classes:
                h, _ = np.histogram(np.log10(x[select]),bins=bins,weights=deltaSquared[select]/countTrees/variance)
                axes[0,1].step(bins[1:],h,where='pre',color=color,ls=style,lw=2,label=label+' '+name)
            # Non-additivity of structural splits. For statistics B and C the jump includes the count added by the split itself
            # (statistic A adds none), which is not part of the non-additivity.
            structural = (massSecond >= 4.0*m) & (n1Parent > 0.0)
            if np.count_nonzero(structural) > 0:
                binsX   = np.linspace(-3.0,np.log10(0.5),15)
                index   = np.digitize(np.log10(x[structural]),binsX)-1
                added   = countAdded[structural] if statisticName != 'statisticA' else 0.0
                ratio   = (delta[structural]-added)/n1Parent[structural]
                slope   = logarithmicSlope(group['n1Table'],np.log10(massTotal[structural]),omegaSplit[structural])
                xs      = x[structural]
                if statisticName == 'statisticC':
                    heuristic = (1.0-xs)**slope-1.0
                else:
                    heuristic = (1.0-xs)**slope+xs**slope-1.0
                centers = 0.5*(binsX[1:]+binsX[:-1])
                def binMedian(values):
                    return np.array([np.nanmedian(values[index == j]) if np.count_nonzero(index == j) >= 10 else np.nan for j in range(len(centers))])
                axes[1,0].plot(10.0**centers,binMedian(ratio    ),color=color,lw=2,marker='o',ms=4,label=label+r' ($1+\alpha={:.2f}$)'.format(np.nanmedian(slope)))
                axes[1,0].plot(10.0**centers,binMedian(heuristic),color=color,lw=1,ls='--')
            massThreshold.append(m)
            sigmaI2      .append((variance                         -mean)/mean**2)
            sigmaI2Split .append((group.attrs['sumDeltaSquaredMean']-mean)/mean**2)
            sigmaI2Error .append(group.attrs['countVarianceError']/mean**2)
        axes[0,0].set_xlabel(r'split redshift $z$')
        axes[0,0].set_ylabel(r'$V(<z)/\mathrm{Var}(N)$')
        axes[0,0].axhline(1.0,color='#888888',lw=1)
        axes[0,0].legend(fontsize=8)
        axes[0,1].set_xlabel(r'$\log_{10} x$  ($x=M^\prime/M$)')
        axes[0,1].set_ylabel(r'fraction of $\mathrm{Var}(N)$ per bin')
        axes[0,1].legend(fontsize=7)
        axes[1,0].plot([],[],color='#555555',lw=1,ls='--',label=r'power law $n_1\propto M^{1+\alpha}$ (local slope)')
        axes[1,0].set_xscale('log')
        axes[1,0].axhline(0.0,color='#888888',lw=1)
        axes[1,0].set_xlabel(r'$x=M^\prime/M$ (structural splits)')
        axes[1,0].set_ylabel(r'median non-additivity $\epsilon$')
        axes[1,0].legend(fontsize=8)
        axes[1,1].errorbar(massThreshold,sigmaI2,yerr=sigmaI2Error,color=colors[0],marker='o',ms=6,lw=2,label=r'$(\mathrm{Var}(N)-\bar{N})/\bar{N}^2$')
        axes[1,1].plot(massThreshold,sigmaI2Split,color=colors[1],marker='s',ms=6,lw=2,label=r'$(\langle\Sigma\Delta^2\rangle-\bar{N})/\bar{N}^2$')
        axes[1,1].axhline(0.0,color='#888888',lw=1)
        axes[1,1].set_xscale('log')
        axes[1,1].set_xlabel(r'threshold mass $m$ [M$_\odot$]')
        axes[1,1].set_ylabel(r'$\sigma_\mathrm{I}^2$')
        axes[1,1].legend(fontsize=8)
        for axis in axes.flat:
            axis.grid(color='#dddddd',lw=0.5)
        fig.tight_layout()
        pdf.savefig(fig)
        plt.close(fig)
print('Plots written to "'+args.outputFileName+'"')
